type RegisteredRuntimeSnapshot = {
  runEpoch: number;
  identityEpoch: number;
  accountId?: string | null;
};
let runtimeSnapshot: () => RegisteredRuntimeSnapshot = () => ({
  runEpoch: 0,
  identityEpoch: 0,
});

/** Current cryptographic account, supplied by chat without importing its store. */
export function currentRuntimeAccountId(): string | null {
  return runtimeSnapshot().accountId ?? null;
}

type RuntimeSnapshot = ReturnType<typeof runtimeSnapshot>;

/** Capture the owner and runtime generation once, then validate both after awaits. */
export function captureChatOwner(
  read: () => RuntimeSnapshot,
  identitySensitive = true,
) {
  const auth = captureOwner();
  const snapshot = read();
  return {
    ...auth,
    run: snapshot.runEpoch,
    current: () => {
      const now = read();
      return (
        auth.owner !== null &&
        auth.current() &&
        now.runEpoch === snapshot.runEpoch &&
        (!identitySensitive || now.identityEpoch === snapshot.identityEpoch)
      );
    },
  };
}

/** Register a read-only snapshot without coupling auxiliary stores back to chat. */
export function registerRuntimeSnapshot(read: typeof runtimeSnapshot) {
  runtimeSnapshot = read;
}

export function captureRuntimeOwner() {
  return captureChatOwner(runtimeSnapshot);
}

/** UI cancellation only: an already-admitted legacy native command is not aborted. */
export function captureOwner() {
  const { user, generation } = useAuth.getState();
  const owner = user?.id ?? null;
  return {
    owner,
    generation,
    current: () => {
      const now = useAuth.getState();
      return now.user?.id === owner && now.generation === generation;
    },
  };
}
import type { ChatState } from "./chat";

type ExpiryState = Pick<
  ChatState,
  | "messages"
  | "intents"
  | "ledger"
  | "incomingFiles"
  | "searchTarget"
  | "expiryNow"
>;

/** One actual-deadline timer per chat owner. No data means no timer and no clock
 * publication. The host retains authoritative expiry; this retires presentation. */
export function startChatExpiry(ports: {
  get: () => ExpiryState;
  current: () => boolean;
  expire: (now: number) => void;
}) {
  const wallStart = Date.now();
  const monotonicStart = performance.now();
  let stopped = false;
  let refreshQueued = false;
  let timer: ReturnType<typeof setTimeout> | undefined;
  const now = () =>
    Math.max(
      ports.get().expiryNow,
      Date.now(),
      wallStart + Math.floor(performance.now() - monotonicStart),
    );
  const nextDeadline = () => {
    const state = ports.get();
    let next = Infinity;
    const take = (at: number | null | undefined) => {
      if (at != null && Number.isFinite(at)) next = Math.min(next, at);
    };
    for (const rows of Object.values(state.messages))
      for (const row of rows) take(row.expiresAtMs);
    for (const intent of Object.values(state.intents))
      take(intent.message.expiresAtMs);
    for (const entries of Object.values(state.ledger))
      for (const entry of Object.values(entries))
        if (!entry.suppressed) take(entry.expiresAtMs);
    for (const file of state.incomingFiles) take(file.expiresAtMs);
    if (state.searchTarget && "context" in state.searchTarget)
      for (const message of state.searchTarget.context)
        if (
          message.expiresAtMs != null &&
          message.expiresAtMs > state.expiryNow
        )
          take(message.expiresAtMs);
    return next;
  };
  const schedule = () => {
    if (timer !== undefined) clearTimeout(timer);
    timer = undefined;
    if (stopped || !ports.current()) return;
    const deadline = nextDeadline();
    if (deadline === Infinity) return;
    // A state publication can run before an already-due timer. Do not defer
    // retirement to another timer tick after cancelling that deadline. A
    // microtask keeps store updates out of the current subscriber dispatch.
    if (deadline <= now()) {
      if (!refreshQueued) {
        refreshQueued = true;
        queueMicrotask(() => {
          refreshQueued = false;
          refresh();
        });
      }
      return;
    }
    // A sparse clock check only while expiring content exists also bounds wall-clock jumps.
    timer = setTimeout(
      refresh,
      Math.min(5 * 60_000, Math.max(0, deadline - now())),
    );
  };
  const refresh = () => {
    if (stopped || !ports.current()) return;
    const at = now();
    if (nextDeadline() <= at) ports.expire(at);
    schedule();
  };
  schedule();
  return {
    schedule,
    refresh,
    stop: () => {
      stopped = true;
      if (timer !== undefined) clearTimeout(timer);
    },
  };
}
